1	export type Item = {
2	  type: string;
3	  material: string;
4	  enchantment: number;
5	  cursed: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Scenario = {
