26	const BASE_PRICES: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	// Expressed as integer percent rather than a 1.1 factor: floating-point
36	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
37	// while scaling by 110 and dividing by 100 stays exact for these prices.
38	const FIRST_CONTRACT_PERCENT = 110;
39	const PERCENT = 100;
40	const CONTRACT_FEE = 5;
41	
42	const basePriceOf = (item: Item): number => BASE_PRICES[item.type];
43	
44	const applyPercent = (amount: number, percent: number): number =>
45	  (amount * percent) / PERCENT;
46	
47	const itemsPriceOf = (step: Step): number =>
48	  step.items.reduce((total, item) => total + basePriceOf(item), 0);
49	
50	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
51	const premiumFor = (itemsPrice: number): number =>
52	  Math.ceil(applyPercent(itemsPrice, FIRST_CONTRACT_PERCENT) + CONTRACT_FEE);
53	
54	const quote = (step: Step): StepResult => ({
55	  premium: premiumFor(itemsPriceOf(step)),
56	});
57	
58	export const run = (scenario: Scenario): ScenarioResult => ({
59	  results: [quote(scenario.steps[0])],
60	});
